pub static DESC_108: PluginDesc = PluginDesc { identifier: "com.plajah.fabula.romantile", label: "Roman Tile", grouping: "Fabula/Stylize", description: "Mosaic of irregular tesserae with grout and per-tile colour averaging — the Roman mosaic look.", contexts: &["OfxImageEffectContextFilter"], clips: &[ClipDesc { name: "Source", optional: false }, ClipDesc { name: "Output", optional: false }], params: PARAMS_108, temporal: false, kernel_passes: &[("main", "\nfloat sh21(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }\nfloat sluma(vec3 c){ return dot(c, vec3(.2126,.7152,.0722)); }\nvec2 srot(vec2 p, float a){ float c=cos(a), s=sin(a); return vec2(c*p.x-s*p.y, s*p.x+c*p.y); }\nvec4 fx(vec2 uv){ vec2 p=uv*uResolution/P0; vec2 id=floor(p); float best=9.0, second=9.0; vec2 bid=id; for(int j=-1;j<=1;j++)for(int i=-1;i<=1;i++){ vec2 c=id+vec2(float(i),float(j)); vec2 jit=vec2(sh21(c),sh21(c+3.3))*P1; vec2 centre=c+0.5+(jit-0.5*P1); float d=length(p-centre); if(d<best){ second=best; best=d; bid=c; } else if(d<second) second=d; } float edge=second-best; vec2 cjit=vec2(sh21(bid),sh21(bid+3.3))*P1; vec2 centre=(bid+0.5+(cjit-0.5*P1))*P0/uResolution; vec4 c=inp(centre); c.rgb*=1.0+(sh21(bid*7.1)-0.5)*P4; float g=smoothstep(P2*0.5,P2*0.5+0.08,edge); vec2 dir=normalize(p-(bid+0.5)+1e-4); float bev=dot(dir,vec2(-0.7,-0.7))*P3*0.25*(1.0-smoothstep(0.2,0.6,edge)); vec3 o=mix(vec3(0.08,0.07,0.06),c.rgb*(1.0+bev),g); return vec4(clamp(o,0.0,1.0),c.a); }")], param_abi: &["size", "irregular", "grout", "bevel", "variance"], header_hash: "985610c1" };
