pub static DESC_129: PluginDesc = PluginDesc { identifier: "com.plajah.fabula.wireremover", label: "Wire Remover", grouping: "Fabula/Key & Utility", description: "Removes a thin wire, rig line or boom by filling it from the pixels on both sides; bind the endpoints to a track to follow the shot.", contexts: &["OfxImageEffectContextFilter"], clips: &[ClipDesc { name: "Source", optional: false }, ClipDesc { name: "Output", optional: false }], params: PARAMS_129, temporal: false, kernel_passes: &[("main", "float wrh(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); } vec4 fx(vec2 uv){ vec4 b=inp(uv); vec2 res=uResolution; vec2 p=uv*res, a=vec2(P0,P1)*res, e=vec2(P2,P3)*res; vec2 ab=e-a; float len=max(length(ab),1e-3); vec2 dir=ab/len, perp=vec2(-dir.y,dir.x); float t=dot(p-a,dir); float along=clamp(t,0.0,len); float d=abs(dot(p-a,perp)); float inSeg=step(0.0,t)*step(t,len); float hw=P4*0.5; float m=(1.0-smoothstep(hw,hw+P5,d))*inSeg; if(m<=0.001) return b; float side=sign(dot(p-a,perp)); vec2 q1=(a+dir*along+perp*(hw+P5)*P6)/res, q2=(a+dir*along-perp*(hw+P5)*P6)/res; vec4 c1=inp(q1), c2=inp(q2); float w=clamp(0.5+dot(p-a,perp)/(2.0*(hw+P5)*P6),0.0,1.0); vec3 fill=mix(c2.rgb,c1.rgb,w); float g=(wrh(p)-0.5)*P7*0.06; fill+=g; return vec4(mix(b.rgb,fill,m),b.a); }")], param_abi: &["x1", "y1", "x2", "y2", "width", "feather", "reach", "noise"], header_hash: "985610c1" };
